// DOM Elements
const restaurantsContainer = document.getElementById('restaurants-container');
const paginationContainer = document.getElementById('pagination');
const searchInput = document.getElementById('search-input');
const cuisineFilter = document.getElementById('cuisine-filter');
const ratingFilter = document.getElementById('rating-filter');
const priceFilter = document.getElementById('price-filter');
const mobileMenuToggle = document.querySelector('.mobile-menu-toggle');
const navLinks = document.querySelector('.nav-links');

// State
let filteredRestaurants = [...restaurants];
let currentPage = 1;
const restaurantsPerPage = 8;

// Render restaurant cards
function renderRestaurants(restaurantsToShow) {
    restaurantsContainer.innerHTML = '';

    if (restaurantsToShow.length === 0) {
        restaurantsContainer.innerHTML = '<p class="no-results">No restaurants found matching your criteria.</p>';
        return;
    }

    restaurantsToShow.forEach((restaurant, index) => {
        const delay = index * 100;
        const restaurantCard = document.createElement('div');
        restaurantCard.className = 'restaurant-card';
        restaurantCard.style.animationDelay = `${delay}ms`;

        // Create star rating
        let stars = '';
        const fullStars = Math.floor(restaurant.rating);
        const halfStar = restaurant.rating % 1 >= 0.5;

        for (let i = 0; i < 5; i++) {
            if (i < fullStars) {
                stars += '<span class="rating-stars">★</span>';
            } else if (i === fullStars && halfStar) {
                stars += '<span class="rating-stars">☆</span>';
            } else {
                stars += '<span class="rating-stars">☆</span>';
            }
        }

        restaurantCard.innerHTML = `
            <img src="${restaurant.image}" alt="${restaurant.name}" class="restaurant-image" onerror="this.src='https://via.placeholder.com/300x200?text=Restaurant+Image'">
            <div class="restaurant-info">
                <h3 class="restaurant-name">${restaurant.name}</h3>
                <p class="restaurant-cuisine">${restaurant.cuisine}</p>
                <div class="restaurant-rating">
                    ${stars}
                    <span class="rating-value">${restaurant.rating}</span>
                </div>
                <p class="restaurant-price">₹${restaurant.price}00 for two</p>
            </div>
        `;

        restaurantsContainer.appendChild(restaurantCard);
    });
}

// Render pagination
function renderPagination() {
    const totalPages = Math.ceil(filteredRestaurants.length / restaurantsPerPage);
    paginationContainer.innerHTML = '';

    if (totalPages <= 1) return;

    for (let i = 1; i <= totalPages; i++) {
        const pageButton = document.createElement('button');
        pageButton.textContent = i;
        pageButton.classList.add('page-btn');
        if (i === currentPage) {
            pageButton.classList.add('active');
