}

// Get restaurants for current page
function getCurrentPageRestaurants() {
    const startIndex = (currentPage - 1) * restaurantsPerPage;
    return filteredRestaurants.slice(startIndex, startIndex + restaurantsPerPage);
}

// Apply filters
function applyFilters() {
    const searchTerm = searchInput.value.toLowerCase();
    const cuisineValue = cuisineFilter.value;
    const ratingValue = ratingFilter.value;
    const priceValue = priceFilter.value;

    filteredRestaurants = restaurants.filter(restaurant => {
        // Search filter
        const matchesSearch = restaurant.name.toLowerCase().includes(searchTerm) || 
                             restaurant.cuisine.toLowerCase().includes(searchTerm);

        // Cuisine filter
        const matchesCuisine = cuisineValue === 'all' || restaurant.cuisine.toLowerCase().includes(cuisineValue);

        // Rating filter
        let matchesRating = true;
        if (ratingValue !== 'all') {
            const minRating = parseFloat(ratingValue);
            matchesRating = restaurant.rating >= minRating;
        }

        // Price filter
        let matchesPrice = true;
        if (priceValue !== 'all') {
            matchesPrice = restaurant.price === parseInt(priceValue);
        }

        return matchesSearch && matchesCuisine && matchesRating && matchesPrice;
    });

    currentPage = 1;
    renderRestaurants(getCurrentPageRestaurants());
    renderPagination();
}

